// src/core/dashboard/dashboard.module.ts

import { FastifyPluginAsync } from 'fastify';
import dashboardRoutes from './dashboard.routes';
import dailyMetricsRoutes from './daily-metrics.routes';
// SPRINT 49: Dashboard Operacional (overview, today, month, sales, inventory)
import operationalDashboardRoutes from '@modules/dashboard/dashboard.routes';

const dashboardModule: FastifyPluginAsync = async (fastify) => {
  await fastify.register(dashboardRoutes);
  await fastify.register(dailyMetricsRoutes, { prefix: '/metrics' });
  // SPRINT 49: Registrar rotas operacionais (overview, today, month, sales, inventory)
  await fastify.register(operationalDashboardRoutes);
};

export default dashboardModule;
export { dashboardModule };











